arguments.function:
() => {
  const text = document.body.innerText || '';
  const lines = text.split(/\n+/).map(s => s.trim()).filter(Boolean);
  const pkg = lines.filter(s => /com\.[a-z0-9.]+/i.test(s) || /Package|包名|Bundle/i.test(s));
  const heading = document.querySelector('h1')?.innerText || '';
  return { heading, pkgLines: pkg.slice(0, 40), sample: lines.slice(0, 80) };
}
